const rows = queries.records.data || [];
const gov = p => ({planRevision: 1, changes: [], acceptances: [], handovers: [], ...(p?.governance || {})});
const revision = p => Number(gov(p).planRevision) || 1;
const pending = p => gov(p).changes.filter(c => c.status === 'Pending');
const delivery = p => !!p?.milestones?.length && p.milestones.every(m => m.status === 'Done') && !(p.blockers || []).some(b => b.status === 'Open');
const acceptance = p => gov(p).acceptances.filter(a => a.planRevision === revision(p)).at(-1);
const accepted = p => acceptance(p)?.outcome === 'Accepted' && pending(p).length === 0;
const ready = p => p?.status === 'Active' && delivery(p) && accepted(p);
const filter = components.portfolioStage?.value, search = String(components.portfolioSearch?.value || '').toLowerCase();
const ps = rows.filter(p => (!filter || filter === 'All' || p.status === filter) && (!search || (p.name + ' ' + p.customer + ' ' + p.owner).toLowerCase().includes(search))).sort((a, b) => String(a.target).localeCompare(String(b.target))).slice(0, 4);
const cards = ps.map(p => {
  const ms = p.milestones || [], done = ms.filter(m => m.status === 'Done').length, risks = (p.blockers || []).filter(b => b.status === 'Open');
  return { id: p.id, customer: p.customer, status: p.status, name: p.name, meta: p.owner + ' · Target ' + p.target + ' · Plan ' + revision(p),
    pct: ms.length ? Math.round(done / ms.length * 100) : 0, counts: done + '/' + ms.length + ' milestones complete',
    blockers: risks.length ? risks.length + ' open blockers' : 'No open blockers', blockersColor: risks.length ? 'var(--cc-warning-systemStatus)' : 'var(--cc-placeholder-text)',
    acceptance: accepted(p) ? '✓ Accepted' : '○ Acceptance pending', acceptanceColor: accepted(p) ? 'var(--cc-success-systemStatus)' : 'var(--cc-placeholder-text)',
    scope: pending(p).length ? pending(p).length + ' scope decisions' : 'Scope up to date',
    nextLine: risks[0]?.title || ms.find(m => m.status !== 'Done')?.title || (ready(p) ? 'Ready for go-live decision' : 'Delivery complete') };
});
const active = rows.filter(r => r.status === 'Active').sort((a, b) => String(a.target).localeCompare(String(b.target)));
const open = active.flatMap(r => (r.blockers || []).filter(x => x.status === 'Open').map(x => ({ title: x.title, project: r.name, owner: 'Owner ' + x.owner })));
return { cards, openCount: open.length + ' open blockers', openBlockers: open.slice(0, 3),
  railNote: open.length ? 'Resolve in the linked project before recording go-live.' : 'No open blockers on active projects.' };

const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const p = (queries.records.data || []).find(r => r.id === variables.recordId);
const gov = x => ({planRevision: 1, changes: [], acceptances: [], handovers: [], ...(x?.governance || {})});
const revision = x => Number(gov(x).planRevision) || 1;
const pending = x => gov(x).changes.filter(c => c.status === 'Pending');
const delivery = x => !!x?.milestones?.length && x.milestones.every(m => m.status === 'Done') && !(x.blockers || []).some(b => b.status === 'Open');
const acceptance = x => gov(x).acceptances.filter(a => a.planRevision === revision(x)).at(-1);
const accepted = x => acceptance(x)?.outcome === 'Accepted' && pending(x).length === 0;
const handover = x => gov(x).handovers.filter(h => h.planRevision === revision(x)).at(-1);
const needs = x => [...(pending(x).length ? ['Scope decision pending'] : []), ...(!delivery(x) ? ['Delivery or blockers incomplete'] : []), ...(!accepted(x) ? ['Current customer acceptance needed'] : [])];
// review-modal context: the change picked in the Review change modal, read from the snapshot taken when the modal opened
const rc = gov(variables.snapshot).changes.find(c => c.id === components.reviewScopechange?.value);
const review = rc ? { title: rc.title + ' · plan ' + rc.baseRevision, target: 'Proposed target: ' + rc.target, scope: rc.scope || '', impact: 'Impact: ' + rc.impact }
                  : { title: 'Select a pending request below to inspect its saved scope and impact.', target: '', scope: '', impact: '' };
if (!p) return { has: false, review, eyebrow: '', name: 'Open a project to see its delivery plan.', meta: '', status: '', milestones: '', pct: 0, needs: '', contextHtml: '', blockers: [], history: [], planEyebrow: '', planName: 'Open a project in the delivery portfolio first, then review its scope and launch evidence here.', planMeta: '', scope: '', readiness: '', acceptHead: '', acceptDetailHtml: '', handHead: '', handDetailHtml: '', counts: '', changes: [], acceptLinesHtml: '', handLinesHtml: '' };
const ms = p.milestones || [], done = ms.filter(m => m.status === 'Done').length, g = gov(p), a = acceptance(p), h = handover(p), bl = p.blockers || [];
return { has: true, review,
  eyebrow: p.customer + ' / PLAN ' + revision(p), name: p.name, meta: p.owner + ' · Target ' + p.target, status: p.status,
  milestones: done + ' / ' + ms.length + ' milestones', pct: ms.length ? Math.round(done / ms.length * 100) : 0, needs: needs(p)[0] || 'Ready for launch owner review',
  contextHtml: e(p.scope) + (bl.length ? '' : '<br><br>No blockers recorded for this project.'),
  blockers: bl.map(b => ({ head: b.title + ' · ' + b.status, detail: b.owner + ' · ' + (b.status === 'Resolved' ? b.resolution : b.note) })),
  history: (p.history || []).slice().reverse().map(x => ({ event: x.event, note: x.note })),
  planEyebrow: 'PLAN ' + revision(p) + ' / CUSTOMER COMMITMENT', planName: p.name, planMeta: p.customer + ' · ' + p.owner + ' · Target ' + p.target, scope: p.scope,
  readiness: p.status === 'Handed over' ? 'Support handover accepted · delivery complete' : p.status === 'Live' ? 'Live · support handover outstanding' : p.status === 'Cancelled' ? 'Cancelled · reopen delivery to continue' : (needs(p).join(' · ') || 'Ready for the launch owner’s decision'),
  acceptHead: a ? a.outcome + ' · ' + a.customer : 'Customer acceptance not recorded for this revision',
  acceptDetailHtml: a ? e(a.reference) + '<br>' + e(a.note) : 'Complete delivery and resolve scope decisions before recording acceptance.',
  handHead: h ? h.outcome + ' · ' + h.owner : 'Support handover pending',
  handDetailHtml: h ? e(h.runbook) + '<br>' + e(h.training) + '<br>' + e(h.note) : 'After go-live, record the runbook, receiving owner and training / access verification.',
  counts: g.acceptances.length + ' acceptance records · ' + g.handovers.length + ' handover records retained',
  changes: g.changes.slice().reverse().map(c => ({ head: c.title + ' · ' + c.status, sub: c.requester + ' · Based on plan ' + c.baseRevision, detailHtml: e(c.impact) + '<br>Target ' + e(c.target) + (c.decisionNote ? '<br>' + e(c.reviewer) + ': ' + e(c.decisionNote) : '') })),
  acceptLinesHtml: (g.changes.length ? '' : 'No scope requests. Propose a change to record its impact and decision before it alters the customer commitment.<br>') + g.acceptances.map(x => 'Plan ' + x.planRevision + ' · ' + e(x.outcome) + ' · ' + e(x.customer) + ' · ' + e(x.reference)).join('<br>'),
  handLinesHtml: g.handovers.map(x => 'Plan ' + x.planRevision + ' · ' + e(x.outcome) + ' · ' + e(x.owner) + ' · ' + e(x.runbook) + '<br>' + e(x.note)).join('<br>') };
